// Helper function to count integers in a sequence of objects
function CountInt(values: seq<object>): int
    reads values
{
    var count := 0;
    var i := 0;
    while i < |values|
        invariant 0 <= count <= i // Count of integers is always non-negative and not greater than i
        invariant i <= |values| // i is always within bounds of values
    {
        if values[i] is int {
            count := count + 1;
        }
        i := i + 1;
    }
    count
}
